3: export function unpack2Bit(b64, width, height) {
4:   const bin = atob(b64);
5:   const out = new Uint8Array(width * height);
6:   let idx = 0;
7:   for (let i = 0; i < bin.length; i++) {
8:     const byte = bin.charCodeAt(i);
9:     if (idx < out.length) out[idx++] = (byte >> 6) & 3;
10:     if (idx < out.length) out[idx++] = (byte >> 4) & 3;
11:     if (idx < out.length) out[idx++] = (byte >> 2) & 3;
12:     if (idx < out.length) out[idx++] = byte & 3;
13:   }
14:   return out;
15: }
