17: export function unpackBytes(b64) {
18:   const bin = atob(b64);
19:   const out = new Uint8Array(bin.length);
20:   for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
21:   return out;
22: }
