345:   // Draw a single 8x8 background tile into an RGBA Uint8ClampedArray buffer
346:   drawTile8x8(
347:     buf,
348:     bufW,
349:     bufH,
350:     destX,
351:     destY,
352:     ts,
353:     tileId,
354:     pal
355:   ) {
356:     const sheet = this.gfxSheets[ts.gfxKey];
357:     if (!sheet) return;
358: 
359:     // Check flower animation on tile $03 (home/vcopy.asm)
360:     if (tileId === 0x03 && ts.anim === "WATER_FLOWER") {
361:       let fIdx = 0;
362:       if (this.animateTiles) {
363:         const c = this.animCounter & 3;
364:         fIdx = c < 2 ? 0 : c === 2 ? 1 : 2;
365:       }
366:       const fPixels = this.flowerFrames[fIdx];
367:       for (let py = 0; py < 8; py++) {
368:         const dy = destY + py;
369:         if (dy < 0 || dy >= bufH) continue;
370:         for (let px = 0; px < 8; px++) {
371:           const dx = destX + px;
372:           if (dx < 0 || dx >= bufW) continue;
373:           const val = fPixels[py * 8 + px];
374:           const c = pal[3 - val];
375:           const off = (dy * bufW + dx) * 4;
376:           buf[off] = c[0];
377:           buf[off + 1] = c[1];
378:           buf[off + 2] = c[2];
379:           buf[off + 3] = 255;
380:         }
381:       }
382:       return;
383:     }
384: 
385:     const tileCol = tileId & 0x0f;
386:     const tileRow = tileId >> 4;
387:     const srcX0 = tileCol * 8;
388:     const srcY0 = tileRow * 8;
389:     if (srcY0 + 8 > sheet.height) return;
390: 
391:     // Check water ripple shift on tile $14
392:     let waterShift = 0;
393:     if (
394:       tileId === 0x14 &&
395:       this.animateTiles &&
396:       (ts.anim === "WATER" || ts.anim === "WATER_FLOWER")
397:     ) {
398:       const c = this.animCounter & 7;
399:       waterShift = c < 4 ? c : 8 - c;
400:     }
401: 
402:     for (let py = 0; py < 8; py++) {
403:       const dy = destY + py;
404:       if (dy < 0 || dy >= bufH) continue;
405:       const sy = srcY0 + py;
406:       for (let px = 0; px < 8; px++) {
407:         const dx = destX + px;
408:         if (dx < 0 || dx >= bufW) continue;
409:         const sx = srcX0 + ((px + waterShift) & 7);
410:         const val = sheet.pixels[sy * sheet.width + sx];
411:         const c = pal[3 - val];
412:         const off = (dy * bufW + dx) * 4;
413:         buf[off] = c[0];
414:         buf[off + 1] = c[1];
415:         buf[off + 2] = c[2];
416:         buf[off + 3] = 255;
417:       }
418:     }
419:   }
