421:   // Draw a 16x16 OAM sprite into RGBA buffer with Game Boy OBP0 transparency
422:   drawSprite16x16(
423:     buf,
424:     bufW,
425:     bufH,
426:     destX,
427:     destY,
428:     spriteKey,
429:     dir = "DOWN",
430:     walking = false,
431:     flipWalk = false,
432:     pal,
433:     underGrass = false,
434:     zone = null,
435:     stepX = 0,
436:     stepY = 0
437:   ) {
438:     const sheet = this.spriteSheets[spriteKey] || this.spriteSheets.red;
439:     if (!sheet) return;
440: 
441:     let frameIdx = 0;
442:     let flipX = false;
443: 
444:     if (sheet.height >= 96) {
445:       if (dir === "DOWN") {
446:         frameIdx = walking ? 3 : 0;
447:         flipX = walking && flipWalk;
448:       } else if (dir === "UP") {
449:         frameIdx = walking ? 4 : 1;
450:         flipX = walking && flipWalk;
451:       } else if (dir === "LEFT") {
452:         frameIdx = walking ? 5 : 2;
453:         flipX = false;
454:       } else if (dir === "RIGHT") {
455:         frameIdx = walking ? 5 : 2;
456:         flipX = true;
457:       }
458:     } else if (sheet.height >= 48) {
459:       if (dir === "DOWN") frameIdx = 0;
460:       else if (dir === "UP") frameIdx = 1;
461:       else if (dir === "LEFT") frameIdx = 2;
462:       else if (dir === "RIGHT") {
463:         frameIdx = 2;
464:         flipX = true;
465:       }
466:     } else {
467:       frameIdx = 0;
468:     }
469: 
470:     const srcY0 = frameIdx * 16;
471:     const accent = this.getSpriteAccentColor(spriteKey, this.paletteMode, pal);
472: 
473:     for (let py = 0; py < 16; py++) {
474:       const dy = destY + py;
475:       if (dy < 0 || dy >= bufH) continue;
476:       for (let px = 0; px < 16; px++) {
477:         const dx = destX + px;
478:         if (dx < 0 || dx >= bufW) continue;
479:         const sx = flipX ? 15 - px : px;
480:         const val = sheet.pixels[(srcY0 + py) * sheet.width + sx];
481:         // In Game Boy OAM (rOBP0): val 3 is transparent, val 2 is white (pal[0]), val 1 is accent/gray (pal[1]), val 0 is black (pal[3])
482:         if (val === 3) continue;
483:         // Authentic tall-grass masking on bottom half of sprite
484:         if (underGrass && py >= 8 && ((px + py) & 1) === 0) continue;
485: 
486:         const c = val === 2 ? pal[0] : val === 1 ? accent : pal[3];
487:         const off = (dy * bufW + dx) * 4;
488:         buf[off] = c[0];
489:         buf[off + 1] = c[1];
490:         buf[off + 2] = c[2];
491:         buf[off + 3] = 255;
492:       }
493:     }
494:   }
