924: function onPlayerStepCompleted() {
925:   const zone = state.currentZone;
926:   const sx = state.player.x;
927:   const sy = state.player.y;
928: 
929:   state.pikachu.stepCounter = (state.pikachu.stepCounter || 0) + 1;
930:   if (state.pikachu.stepCounter % 16 === 0 && state.pikachu.visible) {
931:     modifyPikachuHappiness("WALKING");
932:   }
933: 
934:   updateCoordinatesUI();
935: 
936:   // Check if stepped onto a door / staircase warp
937:   const hitWarp = checkWarpAtStep(zone, sx, sy);
938:   if (hitWarp) {
939:     const ts = engine.tilesetsByConst[zone.tileset];
940:     const tileId = engine.getCollisionTileAtStep(zone, sx, sy);
941:     // In Gen 1, doors, stairs, and cave entrances warp immediately on step;
942:     // indoor exit mats at the bottom edge warp either on step or when pressing Down.
943:     const isBottomExitMat =
944:       zone.romId >= 0x25 &&
945:       sy === zone.height * 2 - 1 &&
946:       !ts.doorSet.has(tileId);
947:     if (!isBottomExitMat) {
948:       const { destConst, destWarpIdx } = resolveWarpDestination(
949:         zone,
950:         hitWarp.warp
951:       );
952:       audio.playSfx("warp");
953:       loadZone(destConst, {
954:         warpIndex: destWarpIdx,
955:         fromOutdoorWarpIndex: hitWarp.warpIdx,
956:       });
957:       return;
958:     }
959:   }
960: 
961:   // Check wild Pokémon encounter in tall grass / caves / water
962:   if (state.wildEncountersEnabled) {
963:     const ts = engine.tilesetsByConst[zone.tileset];
964:     const tileId = engine.getCollisionTileAtStep(zone, sx, sy);
965:     const inGrass = tileId === ts.grassTile;
966:     const inCaveOrDungeon =
967:       zone.category === "dungeon" && zone.wild.grassRate > 0;
968:     const onWater = isWaterTile(zone, tileId) && zone.wild.waterRate > 0;
969: 
970:     if (inGrass && zone.wild.grass.length > 0) {
971:       if (Math.random() < 0.14) {
972:         triggerWildEncounter(zone.wild.grass);
973:       }
974:     } else if (onWater && zone.wild.water.length > 0) {
975:       if (Math.random() < 0.1) {
976:         triggerWildEncounter(zone.wild.water);
977:       }
978:     } else if (inCaveOrDungeon && zone.wild.grass.length > 0) {
979:       if (Math.random() < 0.06) {
980:         triggerWildEncounter(zone.wild.grass);
981:       }
982:     }
983:   }
984: }
