1253: function calcGen1Damage(attacker, defender, move) {
1254:   if (!move || move.power === 0) {
1255:     return { damage: 0, effectiveness: 1.0, crit: false };
1256:   }
1257:   if (move.effect === "SPECIAL_DAMAGE_EFFECT") {
1258:     const fixed =
1259:       move.id === "SONICBOOM"
1260:         ? 20
1261:         : move.id === "DRAGON_RAGE"
1262:         ? 40
1263:         : attacker.level;
1264:     return { damage: fixed, effectiveness: 1.0, crit: false };
1265:   }
1266:   // Gen 1 critical hit rate based on base Speed
1267:   const critChance = Math.min(0.25, (attacker.spd || 50) / 512);
1268:   const crit = Math.random() < critChance;
1269:   const lv = crit ? attacker.level * 2 : attacker.level;
1270: 
1271:   const isSpecial = SPECIAL_TYPES.has(move.type);
1272:   const A = isSpecial ? attacker.spc : attacker.atk;
1273:   const D = Math.max(1, isSpecial ? defender.spc : defender.def);
1274: 
1275:   let baseDmg = Math.floor(
1276:     Math.floor((Math.floor((2 * lv) / 5 + 2) * move.power * A) / D) / 50
1277:   ) + 2;
1278: 
1279:   // STAB (Same-Type Attack Bonus)
1280:   if (attacker.types && attacker.types.includes(move.type)) {
1281:     baseDmg = Math.floor(baseDmg * 1.5);
1282:   }
1283: 
1284:   const effectiveness = getTypeEffectiveness(move.type, defender.types);
1285:   if (effectiveness === 0) {
1286:     return { damage: 0, effectiveness: 0, crit: false };
1287:   }
1288:   baseDmg = Math.floor(baseDmg * effectiveness);
1289: 
1290:   // Random variance (217..255)/255
1291:   const rand = 217 + Math.floor(Math.random() * 39);
1292:   const finalDmg = Math.max(1, Math.floor((baseDmg * rand) / 255));
1293:   return { damage: finalDmg, effectiveness, crit };
1294: }
