1666: export function levelUpPokemon(mon, msgs = [], options = {}) {
1667:   if (!mon || mon.level >= 100) return false;
1668:   mon.level = Math.min(100, mon.level + 1);
1669:   if (mon.species === "PIKACHU") {
1670:     modifyPikachuHappiness("LEVELUP");
1671:   }
1672:   const base = POKEYELLOW_DATA.battle?.pokemonStats?.[mon.species];
1673:   if (base) {
1674:     const lv = mon.level;
1675:     const oldMaxHp = mon.maxHp;
1676:     mon.maxHp = Math.floor(((base.hp + 15) * 2 * lv) / 100) + lv + 10;
1677:     mon.hp = Math.min(mon.maxHp, mon.hp + Math.max(1, mon.maxHp - oldMaxHp));
1678:     mon.atk = Math.floor(((base.atk + 15) * 2 * lv) / 100) + 5;
1679:     mon.def = Math.floor(((base.def + 15) * 2 * lv) / 100) + 5;
1680:     mon.spd = Math.floor(((base.spd + 15) * 2 * lv) / 100) + 5;
1681:     mon.spc = Math.floor(((base.spc + 15) * 2 * lv) / 100) + 5;
1682:     msgs.push(`${mon.nickname} grew to\nlevel ${lv}!`);
1683: 
1684:     // Check data/pokemon/evos_moves.asm learnset for this level
1685:     for (const [learnLv, mId] of base.learnset || []) {
1686:       if (learnLv === lv && !mon.moves.some((mv) => mv.id === mId)) {
1687:         const newMove = getMoveObj(mId);
1688:         if (mon.moves.length < 4) {
1689:           mon.moves.push(newMove);
1690:         } else {
1691:           mon.moves[0] = newMove;
1692:         }
1693:         msgs.push(`${mon.nickname} learned\n${newMove.name}!`);
1694:       }
1695:     }
1696: 
1697:     // Check EVOLVE_LEVEL in data/pokemon/evos_moves.asm (EvolutionAfterBattle)
1698:     for (const evo of base.evolutions || []) {
1699:       if (evo.method === "LEVEL" && lv >= evo.level) {
1700:         if (options.interactive && state.battle) {
1701:           msgs.push({ type: "EVOLVE", mon, target: evo.target });
1702:         } else {
1703:           evolvePokemon(mon, evo.target, msgs);
1704:         }
1705:         break;
1706:       }
1707:     }
1708:   }
1709:   return true;
1710: }
