2199:         const tmp = pMon.moves[b.moveSwapIndex];
2200:         pMon.moves[b.moveSwapIndex] = pMon.moves[b.moveCursor];
2201:         pMon.moves[b.moveCursor] = tmp;
2202:         b.moveSwapIndex = null;
