459:     if (
460:       zone.romId < 0x25 &&
461:       ts.doorSet.has(tileAtWarp) &&
462:       w.y + 1 < zone.height * 2
463:     ) {
464:       return { x: w.x, y: w.y + 1, dir: "DOWN" };
465:     }
466:     return { x: w.x, y: w.y, dir: "DOWN" };
467:   }
