474:   // If the zone has warps, spawn near the first warp or center
475:   if (zone.warps.length > 0) {
476:     const w = zone.warps[0];
477:     if (zone.romId < 0x25 && w.y + 1 < zone.height * 2) {
478:       return { x: w.x, y: w.y + 1, dir: "DOWN" };
479:     }
