import { chromium } from "/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core/index.mjs";
import http from "http";
import fs from "fs";
import path from "path";

const mime = {
  ".html": "text/html",
  ".js": "application/javascript",
  ".css": "text/css",
};

const server = http.createServer((req, res) => {
  const urlPath = req.url.split("?")[0];
  const filePath = path.join(process.cwd(), urlPath === "/" ? "index.html" : urlPath);
  if (!fs.existsSync(filePath)) {
    res.writeHead(404);
    res.end("Not found");
    return;
  }
  const ext = path.extname(filePath);
  res.writeHead(200, { "Content-Type": mime[ext] || "application/octet-stream" });
  fs.createReadStream(filePath).pipe(res);
});

await new Promise((r) => server.listen(0, "127.0.0.1", r));
const port = server.address().port;

const browser = await chromium.launch({ executablePath: "/usr/bin/google-chrome" });
const page = await browser.newPage({ viewport: { width: 412, height: 780 } });
const errors = [];
page.on("pageerror", (e) => errors.push(String(e)));
page.on("console", (msg) => {
  if (msg.type() === "error") errors.push(msg.text());
});

await page.goto(`http://127.0.0.1:${port}/`, { waitUntil: "networkidle" });
await page.waitForTimeout(200);

const stressResult = await page.evaluate(async () => {
  const api = window.POKEYELLOW;

  // 1. Cycle through all 220 canonical zones and render them
  for (let i = 1; i <= 220; i++) {
    api.loadZone(i);
  }
  api.loadZone("PALLET_TOWN");

  // 2. Test Start Menu subviews (POKEDEX, POKEMON, ITEM, RED, SAVE, OPTION)
  api.toggleStartMenu();
  for (let i = 0; i < 6; i++) {
    api.state.startMenu.cursor = i;
    api.state.startMenu.subView = null;
    api.handleStartMenuInput("A");
    api.handleStartMenuInput("B");
  }
  api.toggleStartMenu();

  // 3. Test Audio BGM loop scheduling & teardown (ensure timers stay bounded <= 3)
  const audioBtn = document.getElementById("btn-audio-toggle");
  audioBtn?.click(); // enable BGM
  api.loadZone("VIRIDIAN_CITY");
  api.loadZone("CERULEAN_CITY");
  api.loadZone("PALLET_TOWN");
  audioBtn?.click(); // disable BGM

  // 4. Test Battle + Evolution animation + Cancel + Complete
  api.triggerWildEncounter([15, "PIDGEY"]);
  api.handleBattleInput("DOWN"); // ITEM
  api.handleBattleInput("A"); // open BAG_MENU
  // Use Rare Candy at index 7
  api.state.battle.bagCursor = 7;
  api.handleBattleInput("A");
  api.executeBattleAction("run");

  return {
    currentZone: api.state.currentZone.constName,
    visitedCount: api.state.visitedZones.size,
    battleOpen: Boolean(api.state.battle),
    startMenuOpen: api.state.startMenu.open,
  };
});

await page.waitForTimeout(200);
await page.screenshot({ path: "/tmp/opencode/check.jpg", type: "jpeg", quality: 82 });

console.log("Stress Result:", JSON.stringify(stressResult));
console.log("Errors:", errors);

await browser.close();
server.close();
'

